// CSD_RATIONALE_BEGIN
// Diagnosis of mode_A (140/300 wrong, low-budget, fast): The model generates
// correct short SQL ("SELECT col FROM table") very quickly – a syntactically
// complete parse. CloseSpanWithinBudget then closes at this point since the
// grammar has no valid extension (dead-end at the first complete prefix for
// many simple queries). Meanwhile the 142 genuinely hard examples (JOINs,
// GROUP BY, subqueries, INTERSECT) require the model to *plan* the query
// structure before typing the first token of SQL. With only 5 unconstrained
// preamble tokens, a 4B model has no room to reason about tables, join paths,
// or the right aggregation pattern.
//
// Fix: Extend Phase 1 to 200 unconstrained "thinking" tokens. With guidance
// "Think step by step about the SQL query... Then output: SQL: <<query>>",
// Qwen3.5-4B enters a chain-of-thought reasoning mode, figuring out JOIN
// paths, WHERE conditions, and GROUP BY structure *before* being forced into
// parser-constrained generation. After thinking, Phase 3 spends ALL remaining
// budget (up to 699 steps) in CloseSpanWithinBudget – which tracks the
// longest complete SQL prefix seen – giving maximum room for WHERE/JOIN/ORDER
// BY clauses.
//
// Evidence for thinking helping: The failing rollouts all share a "wrong SQL
// structure" error class (wrong JOIN, wrong aggregation, wrong subquery style)
// rather than a "truncated SQL" error. These are exactly the errors that
// pre-generation reasoning should address.
//
// Budget: Phase1(200) + Phase2(1) + Phase3(699) = 900 == maxSteps.
// Timing: 900 tokens × 0.10 s/token ≤ 90 s/example << 600 s limit.
//
// Guidance kept brief and reasoning-oriented; rule-heavy guidance degraded
// accuracy in attempts 73-75.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained loop): The loop guard includes !insideConstrainedOut,
//   so the implication is vacuously true on every iteration. The only
//   insideConstrainedOut := true assignment is guarded by
//   RenderedEndsWith(generated, "<<"), after which we set
//   currentConstrainedOut := []; parser.IsValidPrefix([]) holds by the method
//   precondition. An EOS break leaves insideConstrainedOut unchanged (false).
//
// Phase 2 (OpenConstrainedSpan): Executes only when !insideConstrainedOut.
//   The helper's postcondition sets insideConstrainedOut := true and
//   currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 (CloseSpanWithinBudget): The helper's postcondition directly
//   guarantees (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)),
//   covering both branches of the implication.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs exactly 1 step and appends at most 1 token
//   (0 on EOS). Each iteration: steps += 1, |generated| grows by <= 1.
//   Invariant holds each iteration.
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly "<<" (1 token).
//   steps += 1, |generated| += 1. Preserved 1:1.
//
// Phase 3: remaining = maxSteps - steps (a nat, >= 0).
//   CloseSpanWithinBudget postcondition: |cg| <= |generated| + remaining.
//   We then set steps += remaining, so steps_new = maxSteps.
//   |cg| <= |generatedPrefix| + steps_old + remaining
//         = |generatedPrefix| + steps_old + (maxSteps - steps_old)
//         = |generatedPrefix| + maxSteps
//         = |generatedPrefix| + steps_new. Invariant preserved.
//   Tokens consumed by dead-end avoidance or EOS inside CloseSpanWithinBudget
//   that are not visibly appended still count against closeBudget, so
//   visible growth is bounded by closeBudget = remaining.
//
// Cost bound: cost = steps = maxSteps <= maxSteps. ✓
// Progress postcondition: maxSteps == 0 ==> first disjunct true.
//   maxSteps > 0 ==> cost = maxSteps > 0 ==> second disjunct true. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Think step by step about what tables, joins, conditions, and aggregations are needed. Then output: SQL: <<complete_query>> using only exact table and column names from the schema.");

var steps: nat := 0;

// Phase 1: Extended unconstrained thinking phase (up to 200 steps).
// Gives the model room to reason about JOIN paths, subquery patterns, GROUP BY,
// and INTERSECT before being forced into parser-constrained SQL generation.
while steps < maxSteps && steps < 200 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if the model has not opened a constrained span naturally.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: CloseSpanWithinBudget using all remaining budget.
// With up to 699 steps available (900 - 200 thinking - 1 open), this helper
// generates SQL forward with dead-end avoidance, tracks the LONGEST complete
// SQL prefix seen across the entire budget, and closes at that point.
// This maximises the chance of generating full WHERE/JOIN/GROUP BY/ORDER BY
// clauses rather than stopping at the first trivially-complete "SELECT col FROM table".
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + remaining;
}

cost := steps;

